// Keep the page behind native dialogs completely still, including on iOS.
let modalScrollY=0,modalScrollLocked=false;
function syncModalScrollLock(){
  const hasOpenDialog=Boolean(document.querySelector('dialog[open]'));
  if(hasOpenDialog&&!modalScrollLocked){
    modalScrollY=window.scrollY;
    document.body.style.top=`-${modalScrollY}px`;
    document.body.classList.add('modal-open');
    modalScrollLocked=true;
  }else if(!hasOpenDialog&&modalScrollLocked){
    document.body.classList.remove('modal-open');
    document.body.style.top='';
    modalScrollLocked=false;
    window.scrollTo(0,modalScrollY);
  }
}
new MutationObserver(syncModalScrollLock).observe(document.body,{subtree:true,attributes:true,attributeFilter:['open']});

function renderJalaliPicker(){
  const first=new Date(jalaliAnchor),parts=persianParts(first);first.setDate(first.getDate()-(parts.day-1));jalaliAnchor=new Date(first);
  document.querySelector('#jalaliMonthTitle').textContent=persianMonthFormatter.format(first);
  const grid=document.querySelector('#jalaliDays');grid.innerHTML='';const leading=(first.getDay()+1)%7;
  for(let i=0;i<leading;i++){const blank=document.createElement('span');blank.className='blank';grid.appendChild(blank)}
  const selected=isoValue(jalaliTarget),today=isoDate(new Date()),month=persianParts(first).month,year=persianParts(first).year;
  for(let cursor=new Date(first);;cursor.setDate(cursor.getDate()+1)){const cursorParts=persianParts(cursor);if(cursorParts.month!==month||cursorParts.year!==year)break;const value=isoDate(cursor),button=document.createElement('button');button.type='button';button.textContent=faDigits(cursorParts.day);button.classList.toggle('selected',value===selected);button.classList.toggle('today',value===today);button.onclick=()=>{setJalaliInput(jalaliTarget,value);document.querySelector('#jalaliPicker').close();jalaliTarget.dispatchEvent(new Event('change',{bubbles:true}))};grid.appendChild(button)}
}
function openJalaliPicker(input){jalaliTarget=input;jalaliAnchor=isoValue(input)?dateFromIso(isoValue(input)):new Date();renderJalaliPicker();document.querySelector('#jalaliPicker').showModal()}
document.querySelectorAll('[data-jalali]').forEach(input=>{input.addEventListener('click',()=>openJalaliPicker(input));input.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openJalaliPicker(input)}})});
document.querySelector('#jalaliPrev').onclick=()=>{jalaliAnchor.setDate(jalaliAnchor.getDate()-1);renderJalaliPicker()};
document.querySelector('#jalaliNext').onclick=()=>{jalaliAnchor.setDate(jalaliAnchor.getDate()+32);renderJalaliPicker()};
document.querySelector('#jalaliToday').onclick=()=>{const value=isoDate(new Date());setJalaliInput(jalaliTarget,value);document.querySelector('#jalaliPicker').close();jalaliTarget.dispatchEvent(new Event('change',{bubbles:true}))};
