function cloneDefault(){return JSON.parse(JSON.stringify(defaultMap))}
function markDirty(){dirty=true;document.querySelector('#saveStatus').textContent='تغییرات منتشر نشده'}
function cafeBaseUrl(){return `/api/cafes/${encodeURIComponent(currentCafeSlug)}/branches/${encodeURIComponent(currentBranch)}`}
function apiUrl(){return `${cafeBaseUrl()}/map`}
function settingsUrl(){return `${cafeBaseUrl()}/settings`}
function availabilityUrl(){return `${cafeBaseUrl()}/availability?date=${state.date}&party_size=${state.guests}`}
function reservationsUrl(){return `${cafeBaseUrl()}/reservations`}
function scheduleUrl(){return `${cafeBaseUrl()}/schedule`}
function activeBranches(){return cafeProfile.branches.filter(branch=>branch.active!==false&&(!managerSession?.branchId||branch.id===managerSession.branchId))}
function activeBranchProfile(){return cafeProfile.branches.find(branch=>branch.slug===currentBranch)||activeBranches()[0]||cafeProfile.branches[0]}
function syncBranchSelectors(){
  const branches=activeBranches(),single=branches.length===1;
  ['branchSelect','controlBranch','opsBranch','smsBranch','paymentsBranch'].forEach(id=>{const select=document.querySelector(`#${id}`);if(!select)return;select.innerHTML='';branches.forEach(branch=>{const option=document.createElement('option');option.value=branch.slug;option.textContent=branch.name;select.appendChild(option)});select.value=currentBranch;select.classList.toggle('single-branch',single)});
}
function applyCafeProfile(profile){
  if(!profile?.configured)return;
  cafeProfile=profile;currentCafeSlug=profile.cafe.slug;if(!profile.branches.some(branch=>branch.slug===currentBranch&&branch.active!==false))currentBranch=activeBranches()[0]?.slug||profile.branches[0].slug;
  syncBranchSelectors();const branch=activeBranchProfile();
  document.querySelector('.cafe-meta span:first-child').textContent=profile.cafe.name;document.querySelector('.cafe-meta span:nth-child(2)').textContent=`${branch.city}، ${branch.name}`;
  document.querySelector('#adminCafeName').textContent=profile.cafe.name;document.querySelector('#adminCafeLocation').textContent=`${branch.city} · ${branch.name}`;
  document.querySelector('.ops-brand b').textContent=`عملیات ${profile.cafe.name}`;document.querySelector('.editor-header b').textContent=`چیدمان ${profile.cafe.name}`;
}
async function loadCafeProfile(){try{const response=await fetch('/api/setup'),profile=await response.json();if(response.ok&&profile.configured)applyCafeProfile(profile);return profile}catch{return {configured:false}}}
function applySettingsToCustomer(){
  const notice=document.querySelector('#customerNoticeBanner'),continueBtn=document.querySelector('#continueBtn');
  notice.textContent=cafeSettings.customerNotice;notice.hidden=!cafeSettings.customerNotice;
  document.querySelector('#durationLabel').textContent=`مدت رزرو: ${faDigits(cafeSettings.reservationDuration)} دقیقه`;
  continueBtn.disabled=!cafeSettings.reservationsEnabled;continueBtn.innerHTML=cafeSettings.reservationsEnabled?'ادامه و انتخاب میز <span>←</span>':'رزرو موقتاً متوقف است';
  document.querySelector('.booking-card').classList.toggle('booking-paused',!cafeSettings.reservationsEnabled);
  if(state.guests>cafeSettings.maxPartySize){state.guests=cafeSettings.maxPartySize;document.querySelector('#guestCount').textContent=faDigits(state.guests)}
}
async function fetchSettings(){try{const response=await fetch(settingsUrl());if(response.ok){cafeSettings=await response.json();applySettingsToCustomer();renderControls();return true}}catch{}document.querySelector('#controlSaveStatus').textContent='دریافت تنظیمات ممکن نیست';return false}
async function fetchMap(){
  document.querySelector('#saveStatus').textContent='در حال دریافت از دیتابیس…';
  const requestedBranch=currentBranch,requestedCafe=currentCafeSlug;
  try{const response=await fetch(apiUrl());if(requestedBranch!==currentBranch||requestedCafe!==currentCafeSlug)return;if(response.status===404){cafeMap=cloneDefault();dirty=true;document.querySelector('#saveStatus').textContent='شعبه جدید؛ آماده انتشار'}else if(response.ok){cafeMap=await response.json();dirty=false;document.querySelector('#saveStatus').textContent='همگام با دیتابیس'}else throw new Error('load');activeArea=visibleAreas()[0]?.id||cafeMap.areas[0]?.id||'main';customerArea=activeArea;selectedId=null;renderEditor();renderCustomerMap()}catch{if(requestedBranch!==currentBranch)return;document.querySelector('#saveStatus').textContent='اتصال برقرار نشد؛ دوباره تلاش کنید';showPublishedToast('خطا در دریافت نقشه')}
}
async function saveMap(){
  document.querySelector('#saveStatus').textContent='در حال ذخیره در دیتابیس…';
  const branch=activeBranchProfile();
  try{const response=await fetch(apiUrl(),{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({cafeName:cafeProfile.cafe.name,branchName:branch.name,city:branch.city,address:branch.address,map:cafeMap})}),data=await safeResponseJson(response,'ذخیره نقشه انجام نشد.');if(!response.ok)throw new Error(data.message||'ذخیره نقشه انجام نشد.');cafeMap=data;dirty=false;document.querySelector('#saveStatus').textContent='همگام با دیتابیس';return true}catch(error){document.querySelector('#saveStatus').textContent='ذخیره نشد؛ تغییرات حفظ شده‌اند';showPublishedToast(readableError(error,'خطا در ذخیره نقشه'));return false}
}

const dates=document.querySelector('#dates'),times=document.querySelector('#times');
function renderDates(){dates.innerHTML='';for(let i=0;i<5;i++){const d=new Date();d.setDate(d.getDate()+i);const date=isoDate(d),parts=new Intl.DateTimeFormat('fa-IR-u-ca-persian',{weekday:'long',day:'numeric',month:'long'}).format(d),day=new Intl.DateTimeFormat('fa-IR-u-ca-persian',{day:'numeric'}).format(d),weekday=i===0?'امروز':parts.split(' ')[0],b=document.createElement('button');if(i===0&&!state.date){state.date=date;state.dateLabel=parts}b.className='date'+(state.date===date?' selected':'');b.innerHTML=`<small>${weekday}</small><b>${day}</b>`;b.onclick=async()=>{state.date=date;state.dateLabel=parts;state.time='';renderDates();await fetchAvailability()};dates.appendChild(b)}}
function renderTimes(){times.innerHTML='';const data=state.availability;if(!data){times.innerHTML='<span class="slot-message">در حال بررسی ظرفیت…</span>';return}if(data.closed||!data.slots.length){times.textContent=data.reason||'در این روز زمان آزادی وجود ندارد.';return}data.slots.forEach(slot=>{const b=document.createElement('button');b.className='time'+(state.time===slot.time?' selected':'');b.textContent=faDigits(slot.time);b.disabled=!slot.available;b.title=slot.available?`${faDigits(slot.remaining)} میز آزاد`:'تکمیل ظرفیت';b.onclick=()=>{state.time=slot.time;state.availableTableIds=new Set(slot.tableIds);renderTimes()};times.appendChild(b)})}
