renderDates();
const count=document.querySelector('#guestCount');async function changeGuests(delta){state.guests=Math.max(1,Math.min(cafeSettings.maxPartySize,state.guests+delta));count.textContent=faDigits(state.guests);state.time='';await fetchAvailability()}document.querySelector('#plus').onclick=()=>changeGuests(1);document.querySelector('#minus').onclick=()=>changeGuests(-1);

