  areas.forEach(area=>{const button=document.createElement('button'),count=cafeMap.tables.filter(table=>table.area===area.id).length;button.type='button';button.className=area.id===customerArea?'active':'';button.innerHTML=`<span>${area.kind==='outdoor'?'☀':'⌂'}</span><b>${escapeHtml(area.name)}</b><small>${faDigits(count)} میز</small>`;button.onclick=()=>{customerArea=area.id;state.table='';state.tableId='';const confirmButton=document.querySelector('#confirmBtn');confirmButton.disabled=true;confirmButton.textContent='یک میز را انتخاب کنید';renderCustomerMap()};tabs.appendChild(button)});
  floor.classList.toggle('outdoor',current?.kind==='outdoor');floor.innerHTML=current?.kind==='outdoor'?'<span class="outdoor-label">فضای باز</span>':'<span class="window-label">پنجره سرتاسری</span><div class="bar">بار و صندوق</div>';
