document.querySelector('#payDeposit').onclick=async()=>{if(!pendingPayment)return;const button=document.querySelector('#payDeposit');button.disabled=true;button.textContent='در حال پرداخت آزمایشی…';try{const response=await fetch(`/api/reservations/${encodeURIComponent(pendingPayment.trackingCode)}/pay`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({mobile:pendingPayment.mobile})}),data=await response.json();if(!response.ok)throw new Error(data.message||'پرداخت انجام نشد.');document.querySelector('#depositPayment').innerHTML=`<b class="payment-success">پرداخت موفق · رزرو تأیید شد</b><small>شماره پیگیری: ${escapeHtml(data.reference||'آزمایشی')}</small>`;document.querySelector('.success-dialog h2').textContent='میزت رزرو شد!';document.querySelector('#successText').textContent=`${state.table} برای ${faDigits(state.guests)} نفر در ساعت ${faDigits(state.time)} تأیید شد.`;pendingPayment=null}catch(error){button.disabled=false;button.textContent=error.message}}
