let smsData=null;
function notificationsUrl(path=''){return `${cafeBaseUrl()}/notifications${path}`}
function smsStatusLabel(status){return ({sent:'ارسال‌شده',demo_sent:'ثبت آزمایشی',queued:'در صف یادآوری',sending:'در حال ارسال',failed:'ناموفق',cancelled:'لغوشده'})[status]||status}
function renderSms(){if(!smsData)return;const mode=document.querySelector('#smsMode');mode.classList.toggle('connected',smsData.mode==='kavenegar');mode.querySelector('b').textContent=smsData.mode==='kavenegar'?'کاوه‌نگار متصل است':'حالت آزمایشی';mode.querySelector('small').textContent=smsData.mode==='kavenegar'?'پیام‌ها از طریق قالب‌های تأییدشده کاوه‌نگار ارسال می‌شوند.':'متن پیامک ثبت می‌شود اما پیام واقعی ارسال نمی‌شود.';document.querySelector('#smsConfirmationEnabled').checked=smsData.settings.confirmationEnabled;document.querySelector('#smsReminderEnabled').checked=smsData.settings.reminderEnabled;document.querySelector('#smsReminderMinutes').value=String(smsData.settings.reminderMinutes);document.querySelector('#smsSent').textContent=faDigits(smsData.stats.sent);document.querySelector('#smsQueued').textContent=faDigits(smsData.stats.queued);document.querySelector('#smsFailed').textContent=faDigits(smsData.stats.failed);const list=document.querySelector('#smsList');list.innerHTML='';if(!smsData.messages.length){list.innerHTML='<div class="sms-empty">هنوز پیامکی ثبت نشده است.<br>با ثبت رزرو جدید، پیام تأیید اینجا نمایش داده می‌شود.</div>';return}smsData.messages.forEach(message=>{const item=document.createElement('article');item.className=`sms-row ${message.status}`;const moment=message.sentAt?`ارسال: ${formatPersianDate(message.sentAt)} · ${faDigits(String(message.sentAt).slice(11,16))}`:`موعد: ${formatPersianDate(message.scheduledAt)} · ${faDigits(String(message.scheduledAt).slice(11,16))}`;item.innerHTML=`<div class="sms-row-top"><span class="sms-kind">${message.kind==='confirmation'?'تأیید رزرو':'یادآوری'}</span><em>${smsStatusLabel(message.status)}</em></div><h3>${escapeHtml(message.customerName)} · ${faDigits(message.mobile)}</h3><p>${escapeHtml(message.message)}</p><small>${moment}${message.error?` · ${escapeHtml(message.error)}`:''}</small>`;list.appendChild(item)})}
