function tableSize(t){return t.shape==='rect'?{w:118,h:70}:{w:76,h:76}}
function startDrag(e){e.stopPropagation();const id=e.currentTarget.dataset.id,t=cafeMap.tables.find(x=>x.id===id),el=e.currentTarget,startX=e.clientX,startY=e.clientY,originX=t.x,originY=t.y;let moved=false;selectedId=id;document.querySelectorAll('.editor-table').forEach(item=>item.classList.toggle('selected',item===el));el.setPointerCapture(e.pointerId);const move=ev=>{const dx=ev.clientX-startX,dy=ev.clientY-startY;if(!moved&&Math.hypot(dx,dy)<5)return;moved=true;el.classList.add('dragging');const size=tableSize(t);t.x=Math.max(0,Math.min(820-size.w,originX+dx/zoom));t.y=Math.max(0,Math.min(520-size.h,originY+dy/zoom));el.style.left=`${t.x}px`;el.style.top=`${t.y}px`};const finish=ev=>{el.classList.remove('dragging');el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',finish);el.removeEventListener('pointercancel',finish);if(ev.type==='pointercancel')return;if(moved)markDirty();else selectTable(id)};el.addEventListener('pointermove',move);el.addEventListener('pointerup',finish);el.addEventListener('pointercancel',finish)}
function addTable(shape){const n=cafeMap.tables.length+1,t={id:`t${Date.now()}`,area:activeArea,name:`میز ${faDigits(n)}`,shape,capacity:shape==='rect'?6:2,x:285+(n%3)*35,y:165+(n%4)*32,reservable:true};cafeMap.tables.push(t);selectedId=t.id;markDirty();renderEditor()}
document.querySelectorAll('[data-add-shape]').forEach(b=>b.onclick=()=>addTable(b.dataset.addShape));
function addArea(name,kind){const clean=String(name||'').trim(),existing=cafeMap.areas.find(area=>area.name===clean);if(!clean)return;if(existing){if(cafeMap.spaceMode!=='both'&&existing.kind!==cafeMap.spaceMode)cafeMap.spaceMode='both';activeArea=existing.id;selectedId=null;markDirty();renderEditor();return}const id=`area-${Date.now()}`;cafeMap.areas.push({id,name:clean,kind:kind==='outdoor'?'outdoor':'indoor'});cafeMap.spaceMode=derivedSpaceMode();activeArea=id;selectedId=null;markDirty();renderEditor()}
function removeArea(id){const area=cafeMap.areas.find(item=>item.id===id),tableCount=cafeMap.tables.filter(table=>table.area===id).length;if(!area||cafeMap.areas.length===1)return;if(!confirm(`بخش «${area.name}»${tableCount?` و ${faDigits(tableCount)} میز آن`:''} حذف شود؟`))return;cafeMap.areas=cafeMap.areas.filter(item=>item.id!==id);cafeMap.tables=cafeMap.tables.filter(table=>table.area!==id);cafeMap.spaceMode=derivedSpaceMode();if(activeArea===id)activeArea=cafeMap.areas[0].id;selectedId=null;markDirty();renderEditor()}
function setSpaceMode(mode){if(!['indoor','outdoor','both'].includes(mode)||mode===cafeMap.spaceMode)return;if(mode==='both'){if(!cafeMap.areas.some(area=>area.kind==='indoor'))cafeMap.areas.push({id:`area-${Date.now()}-in`,name:'سالن اصلی',kind:'indoor'});if(!cafeMap.areas.some(area=>area.kind==='outdoor'))cafeMap.areas.push({id:`area-${Date.now()}-out`,name:'تراس',kind:'outdoor'})}else if(!cafeMap.areas.some(area=>area.kind===mode))cafeMap.areas.push({id:`area-${Date.now()}`,name:mode==='outdoor'?'تراس':'سالن اصلی',kind:mode});cafeMap.spaceMode=mode;activeArea=visibleAreas()[0].id;customerArea=activeArea;selectedId=null;markDirty();renderEditor()}
document.querySelectorAll('[data-space-mode]').forEach(button=>button.onclick=()=>setSpaceMode(button.dataset.spaceMode));
const areaAddPanel=document.querySelector('#areaAddPanel'),areaAddToggle=document.querySelector('#areaAddToggle'),areaPreset=document.querySelector('#areaPreset'),customAreaFields=document.querySelector('#customAreaFields');
function setAreaAddPanel(open){areaAddPanel.hidden=!open;areaAddToggle.setAttribute('aria-expanded',String(open));areaAddToggle.textContent=open?'× بستن':'+ بخش جدید'}
areaAddToggle.onclick=()=>setAreaAddPanel(areaAddPanel.hidden);areaPreset.onchange=()=>{const custom=areaPreset.value.startsWith('custom|');customAreaFields.hidden=!custom;if(custom)document.querySelector('#customAreaName').focus()};
document.querySelector('#addArea').onclick=()=>{const [presetName,presetKind]=areaPreset.value.split('|'),custom=presetName==='custom',input=document.querySelector('#customAreaName'),name=custom?input.value:presetName,kind=custom?document.querySelector('#customAreaKind').value:presetKind;if(!String(name||'').trim()){input.focus();return}addArea(name,kind);input.value='';setAreaAddPanel(false)};
document.querySelector('#customAreaName').onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();document.querySelector('#addArea').click()}};
function setMapTools(open){document.querySelector('.editor-sidebar').classList.toggle('mobile-open',open);document.querySelector('.editor-shell').classList.toggle('tools-open',open)}
document.querySelector('#mapToolsToggle').onclick=()=>setMapTools(true);document.querySelector('#closeMapTools').onclick=()=>setMapTools(false);
document.querySelector('#tableName').oninput=e=>{const t=selectedTable();if(!t)return;t.name=e.target.value||'بدون نام';markDirty();renderEditor()};
document.querySelector('#capacityMinus').onclick=()=>changeCapacity(-1);document.querySelector('#capacityPlus').onclick=()=>changeCapacity(1);
function changeCapacity(delta){const t=selectedTable();if(!t)return;t.capacity=Math.max(1,Math.min(20,t.capacity+delta));markDirty();renderEditor()}
document.querySelector('#tableShape').onchange=e=>{const t=selectedTable();if(!t)return;t.shape=e.target.value;markDirty();renderEditor()};
document.querySelector('#tableReservable').onchange=e=>{const t=selectedTable();if(!t)return;t.reservable=e.target.checked;markDirty();renderEditor()};
document.querySelector('#deleteTable').onclick=()=>{cafeMap.tables=cafeMap.tables.filter(t=>t.id!==selectedId);selectedId=null;markDirty();renderEditor()};
document.querySelector('#duplicateTable').onclick=()=>{const t=selectedTable();if(!t)return;const copy={...t,id:`t${Date.now()}`,name:`${t.name} کپی`,x:Math.min(680,t.x+28),y:Math.min(410,t.y+28)};cafeMap.tables.push(copy);selectedId=copy.id;markDirty();renderEditor()};
document.querySelector('#zoomIn').onclick=()=>{zoom=Math.min(1.25,zoom+.1);document.querySelector('#zoomValue').textContent=`${Math.round(zoom*100)}٪`;renderEditor()};document.querySelector('#zoomOut').onclick=()=>{zoom=Math.max(.7,zoom-.1);document.querySelector('#zoomValue').textContent=`${Math.round(zoom*100)}٪`;renderEditor()};
document.querySelector('#resetMap').onclick=()=>{if(!confirm('چیدمان دمو بازنشانی شود؟'))return;cafeMap=cloneDefault();activeArea='main';customerArea='main';selectedId=null;markDirty();renderEditor()};
function showPublishedToast(message='نقشه با موفقیت منتشر شد'){const toast=document.querySelector('#editorToast');toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2200)}
document.querySelector('#publishMap').onclick=async()=>{if(await saveMap()){renderCustomerMap();showPublishedToast()}};
document.querySelector('#previewMap').onclick=()=>{mapPreviewMode=true;document.querySelector('#selectionSummary').textContent='پیش‌نمایش چیدمان این شعبه · تغییرات هنوز منتشر نشده‌اند';document.querySelector('#confirmBtn').hidden=true;editor.close();tableDialog.showModal();renderCustomerMap()};
tableDialog.addEventListener('close',()=>{if(!mapPreviewMode)return;mapPreviewMode=false;document.querySelector('#confirmBtn').hidden=false;renderCustomerMap();if(!editor.open)editor.showModal()});

function renderControls(){
  document.querySelector('#reservationsEnabled').checked=cafeSettings.reservationsEnabled;document.querySelector('#autoConfirm').checked=cafeSettings.autoConfirm;document.querySelector('#reservationDuration').value=String(cafeSettings.reservationDuration);document.querySelector('#bufferMinutes').value=String(cafeSettings.bufferMinutes);document.querySelector('#maxPartyValue').textContent=faDigits(cafeSettings.maxPartySize);document.querySelector('#customerNotice').value=cafeSettings.customerNotice;document.querySelector('#noticeCount').textContent=faDigits(cafeSettings.customerNotice.length);
  const light=document.querySelector('#reservationStatusLight');light.classList.toggle('offline',!cafeSettings.reservationsEnabled);document.querySelector('#reservationStatusTitle').textContent=cafeSettings.reservationsEnabled?'رزرو آنلاین فعال است':'رزرو آنلاین متوقف است';document.querySelector('#reservationStatusCaption').textContent=cafeSettings.reservationsEnabled?'مشتری‌ها می‌توانند میز رزرو کنند':'فرم رزرو برای مشتری غیرفعال است';
}
function readControls(){cafeSettings={...cafeSettings,reservationsEnabled:document.querySelector('#reservationsEnabled').checked,autoConfirm:document.querySelector('#autoConfirm').checked,reservationDuration:Number(document.querySelector('#reservationDuration').value),bufferMinutes:Number(document.querySelector('#bufferMinutes').value),maxPartySize:cafeSettings.maxPartySize,customerNotice:document.querySelector('#customerNotice').value.trim()};renderControls()}
document.querySelector('#reservationsEnabled').onchange=readControls;document.querySelector('#autoConfirm').onchange=readControls;document.querySelector('#reservationDuration').onchange=readControls;document.querySelector('#bufferMinutes').onchange=readControls;
document.querySelector('#customerNotice').oninput=e=>{cafeSettings.customerNotice=e.target.value;document.querySelector('#noticeCount').textContent=faDigits(e.target.value.length)};
document.querySelector('#maxPartyMinus').onclick=()=>{cafeSettings.maxPartySize=Math.max(1,cafeSettings.maxPartySize-1);renderControls()};document.querySelector('#maxPartyPlus').onclick=()=>{cafeSettings.maxPartySize=Math.min(20,cafeSettings.maxPartySize+1);renderControls()};
document.querySelector('#saveControls').onclick=async()=>{readControls();const status=document.querySelector('#controlSaveStatus'),branch=activeBranchProfile();status.textContent='در حال ذخیره…';try{const response=await fetch(settingsUrl(),{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({...cafeSettings,cafeName:cafeProfile.cafe.name,branchName:branch.name,city:branch.city,address:branch.address})});if(!response.ok)throw new Error('save');cafeSettings=await response.json();renderControls();applySettingsToCustomer();await fetchAvailability();status.textContent='تغییرات با موفقیت اعمال شد'}catch{status.textContent='ذخیره انجام نشد؛ دوباره تلاش کنید'}};

const weekNames=['یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه','شنبه'];
function renderSchedule(){const wrap=document.querySelector('#weekHours');wrap.innerHTML='';cafeSchedule.hours.forEach(h=>{const row=document.createElement('div');row.className='hour-row';row.innerHTML=`<b>${weekNames[h.weekday]}</b><label><input type="checkbox" data-closed="${h.weekday}" ${h.closed?'checked':''}> تعطیل</label><input type="time" data-open="${h.weekday}" value="${h.openTime}" ${h.closed?'disabled':''}><span>تا</span><input type="time" data-close="${h.weekday}" value="${h.closeTime}" ${h.closed?'disabled':''}>`;row.querySelector('[data-closed]').onchange=e=>{h.closed=e.target.checked;renderSchedule()};row.querySelector('[data-open]').onchange=e=>h.openTime=e.target.value;row.querySelector('[data-close]').onchange=e=>h.closeTime=e.target.value;wrap.appendChild(row)});const list=document.querySelector('#closureList');list.innerHTML='';cafeSchedule.closures.forEach((c,index)=>{const item=document.createElement('div');item.innerHTML=`<span>${formatPersianDate(c.startDate)} تا ${formatPersianDate(c.endDate)}${c.reason?` · ${escapeHtml(c.reason)}`:''}</span><button type="button">حذف</button>`;item.querySelector('button').onclick=()=>{cafeSchedule.closures.splice(index,1);renderSchedule()};list.appendChild(item)})}
async function fetchSchedule(){const status=document.querySelector('#scheduleStatus');status.textContent='در حال دریافت تقویم…';try{const response=await fetch(scheduleUrl()),data=await response.json();if(!response.ok)throw new Error(data.message||'دریافت تقویم ممکن نیست');cafeSchedule=data;renderSchedule();status.textContent=''}catch(err){status.textContent=err.message}}
document.querySelector('#addClosure').onclick=()=>{const start=isoValue(document.querySelector('#closureStart')),end=isoValue(document.querySelector('#closureEnd')),reason=document.querySelector('#closureReason').value.trim(),status=document.querySelector('#scheduleStatus');if(!start||!end||end<start){status.textContent='بازه تاریخ تعطیلی را درست انتخاب کنید.';return}cafeSchedule.closures.push({startDate:start,endDate:end,reason});setJalaliInput(document.querySelector('#closureStart'),'');setJalaliInput(document.querySelector('#closureEnd'),'');document.querySelector('#closureReason').value='';status.textContent='';renderSchedule()};
document.querySelector('#saveSchedule').onclick=async()=>{const button=document.querySelector('#saveSchedule'),status=document.querySelector('#scheduleStatus');button.disabled=true;status.textContent='در حال ذخیره…';try{const response=await fetch(scheduleUrl(),{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(cafeSchedule)}),data=await response.json();if(!response.ok)throw new Error(data.message||'ذخیره انجام نشد');cafeSchedule=data;renderSchedule();await fetchAvailability();status.textContent='تقویم شعبه ذخیره شد.'}catch(err){status.textContent=err.message}finally{button.disabled=false}};

// Phase 2: live operations dashboard
const opsDialog=document.querySelector('#opsDialog'),opsReservationDialog=document.querySelector('#opsReservationDialog'),waitlistDialog=document.querySelector('#waitlistDialog');
let opsData=null,opsRefreshTimer=null,opsAreaId='';
const escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
function operationsUrl(path=''){return `${cafeBaseUrl()}/operations${path}`}
function opsStatusLabel(status){return ({pending:'در انتظار',confirmed:'تأیید شده',arrived:'مشتری رسیده',completed:'تکمیل شده',cancelled:'لغو شده',no_show:'عدم مراجعه'})[status]||status}
function sourceLabel(source){return source==='phone'?'تلفنی':source==='walk_in'?'حضوری':'آنلاین'}
async function fetchOperations(){const sync=document.querySelector('#opsSync');sync.textContent='در حال تازه‌سازی…';try{const date=isoValue(document.querySelector('#opsDate'))||isoDate(new Date()),time=document.querySelector('#opsFloorTime').value||roundedFloorTime(),response=await fetch(`${operationsUrl()}?date=${date}&time=${encodeURIComponent(time)}`),data=await response.json();if(!response.ok)throw new Error(data.message||'دریافت عملیات ممکن نیست');opsData=data;renderOperations();sync.textContent=`به‌روز شد · ${new Intl.DateTimeFormat('fa-IR',{hour:'2-digit',minute:'2-digit'}).format(new Date())}`}catch(err){sync.textContent=err.message}}
function renderOperations(){if(!opsData)return;const s=opsData.stats,cards=document.querySelectorAll('#opsKpis article');[[s.reservations,'رزرو امروز'],[s.guests,'مهمان'],[`${s.occupiedTables}/${s.totalTables}`,'میز قفل‌شده'],[s.remainingCapacity,'صندلی آزاد'],[s.delayed+s.waiting,'نیازمند توجه']].forEach(([value,label],i)=>{cards[i].querySelector('span').textContent=label;cards[i].querySelector('strong').textContent=faDigits(value)});document.querySelector('#opsNextReservation').textContent=opsData.nextReservation?`رزرو بعدی: ${opsData.nextReservation.customerName}، ساعت ${faDigits(opsData.nextReservation.time)}`:'رزرو فعال دیگری باقی نمانده';renderOperationalReservations();renderOpsAreas();renderOpsMap();renderWaitlist();fillOpsTables()}
function renderOperationalReservations(){const list=document.querySelector('#opsReservationList'),query=latinDigits(document.querySelector('#opsSearch').value).trim().toLowerCase(),filter=document.querySelector('#opsStatusFilter').value,rows=opsData.reservations.filter(r=>(filter==='all'||r.status===filter)&&(!query||`${r.customerName} ${r.mobile} ${r.trackingCode}`.toLowerCase().includes(query)));list.innerHTML='';if(!rows.length){list.innerHTML='<div class="ops-empty">رزروی با این فیلتر پیدا نشد.<br>رزرو تلفنی یا حضوری را از دکمه بالا ثبت کنید.</div>';return}rows.forEach(r=>{const row=document.createElement('div');row.className='ops-reservation-row';row.innerHTML=`<time>${faDigits(r.time)}</time><div><h4>${escapeHtml(r.customerName)}</h4><p>${faDigits(r.partySize)} نفر · ${escapeHtml(r.tables.join('، ')||'بدون میز')} <span class="source">${sourceLabel(r.source)}</span></p></div><em class="ops-status ${r.status}">${opsStatusLabel(r.status)}</em>`;if(hasManagerPermission('reservations.write'))row.onclick=()=>openOpsReservation(r);else row.classList.add('readonly');list.appendChild(row)})}
function renderOpsAreas(){const tabs=document.querySelector('#opsAreaTabs'),areas=[...new Map(opsData.tables.map(table=>[table.areaId,{id:table.areaId,name:table.areaName}])).values()];if(!areas.some(area=>area.id===opsAreaId))opsAreaId=areas[0]?.id||'';tabs.innerHTML='';tabs.hidden=areas.length<2;areas.forEach(area=>{const button=document.createElement('button');button.type='button';button.className=area.id===opsAreaId?'active':'';button.textContent=area.name;button.onclick=()=>{opsAreaId=area.id;renderOpsAreas();renderOpsMap()};tabs.appendChild(button)})}
function renderOpsMap(){const floor=document.querySelector('#opsFloor');floor.innerHTML='';const width=Math.max(320,floor.clientWidth||500),height=Math.max(380,floor.clientHeight||430),tables=opsData.tables.filter(table=>!opsAreaId||table.areaId===opsAreaId);tables.forEach(t=>{const b=document.createElement('button'),w=t.shape==='rect'?92:62;b.className=`ops-table ${t.shape} ${t.liveStatus}`;b.style.left=`${Math.round(14+Math.max(0,Math.min(1,t.x/Math.max(1,820-(t.shape==='rect'?118:76))))*Math.max(0,width-w-28))}px`;b.style.top=`${Math.round(14+Math.max(0,Math.min(1,t.y/Math.max(1,520-(t.shape==='rect'?70:76))))*Math.max(0,height-62-28))}px`;const reservationLabel=t.reservation?`${t.reservation.customerName?escapeHtml(t.reservation.customerName)+' · ':''}${faDigits(t.reservation.time)}`:`${faDigits(t.capacity)} نفره`;b.innerHTML=`<span><b>${escapeHtml(t.name)}</b><small>${reservationLabel}</small></span>`;b.onclick=e=>{if(t.canQuickLock&&hasManagerPermission('reservations.write'))quickLockTable(t,b);else openTablePopover(e,t)};floor.appendChild(b)})}
async function quickLockTable(table,button){button.disabled=true;button.classList.add('locking');document.querySelector('#opsFloorHint').textContent=`در حال قفل‌کردن ${table.name}…`;const payload={customerName:'مهمان حضوری',mobile:'',source:'walk_in',status:'confirmed',date:isoValue(document.querySelector('#opsDate'))||tehranClientNow().date,time:document.querySelector('#opsFloorTime').value||roundedFloorTime(),partySize:Math.min(table.capacity,cafeSettings.maxPartySize||20),tableIds:[table.id],notes:'ثبت سریع از نقشه سالن',internalNotes:'قفل سریع میز برای مراجعه حضوری'};try{const response=await fetch(operationsUrl('/reservations'),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw new Error(data.message||'قفل میز انجام نشد');document.querySelector('#opsFloorHint').textContent=`${table.name} برای ساعت ${faDigits(payload.time)} قفل شد`;await Promise.all([fetchOperations(),fetchAvailability()])}catch(error){button.disabled=false;button.classList.remove('locking');document.querySelector('#opsFloorHint').textContent=error.message}}
async function quickReleaseTable(table,button){button.disabled=true;const response=await fetch(`${operationsUrl('/reservations')}/${encodeURIComponent(table.reservation.trackingCode)}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({status:'cancelled'})}),data=await response.json();if(!response.ok){button.disabled=false;document.querySelector('#opsFloorHint').textContent=data.message||'آزادکردن میز انجام نشد';return}document.querySelector('#opsFloorHint').textContent=`${table.name} آزاد شد`;document.querySelector('.table-popover')?.remove();await Promise.all([fetchOperations(),fetchAvailability()])}
function openTablePopover(event,table){document.querySelector('.table-popover')?.remove();const box=document.createElement('div'),canEdit=hasManagerPermission('tables.write'),canRelease=hasManagerPermission('reservations.write')&&table.reservation?.source==='walk_in'&&table.reservation?.customerName==='مهمان حضوری';box.className='table-popover';box.innerHTML=`<b>${escapeHtml(table.name)}</b><small>${table.reservation?`${table.reservation.customerName?escapeHtml(table.reservation.customerName)+' · ':''}ساعت ${faDigits(table.reservation.time)}`:'بدون رزرو فعال'}</small>${canRelease?'<button class="quick-release">آزادکردن میز</button>':''}${canEdit?`<div><button data-status="available" class="${table.manualStatus==='available'?'active':''}">آماده</button><button data-status="dirty" class="${table.manualStatus==='dirty'?'active':''}">نظافت</button><button data-status="inactive" class="${table.manualStatus==='inactive'?'active':''}">غیرفعال</button></div>`:'<p>دسترسی شما فقط برای مشاهده است.</p>'}`;const floor=document.querySelector('#opsFloor'),rect=floor.getBoundingClientRect();box.style.left=`${Math.max(8,Math.min(rect.width-220,event.clientX-rect.left-105))}px`;box.style.top=`${Math.max(8,Math.min(rect.height-170,event.clientY-rect.top+20))}px`;box.querySelector('.quick-release')?.addEventListener('click',event=>quickReleaseTable(table,event.currentTarget));box.querySelectorAll('[data-status]').forEach(btn=>btn.onclick=async()=>{await updateTableStatus(table.id,btn.dataset.status);box.remove()});floor.appendChild(box)}
async function updateTableStatus(id,status){const response=await fetch(`${operationsUrl('/tables')}/${encodeURIComponent(id)}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({status})});if(response.ok)await fetchOperations()}
function renderWaitlist(){const list=document.querySelector('#opsWaitlist'),waiting=opsData.waitlist.filter(w=>w.status==='waiting');document.querySelector('#waitCount').textContent=waiting.length?`${faDigits(waiting.length)} گروه منتظر`:'بدون مشتری منتظر';list.innerHTML='';if(!opsData.waitlist.length){list.innerHTML='<div class="ops-empty">لیست انتظار خالی است</div>';return}opsData.waitlist.forEach(w=>{const item=document.createElement('div');item.className='wait-row';const elapsed=Math.max(0,Math.floor((Date.now()-new Date(w.createdAt).getTime())/60000));item.innerHTML=`<header><b>${escapeHtml(w.customerName)}</b><time>${faDigits(elapsed)} دقیقه</time></header><p>${faDigits(w.partySize)} نفر · انتظار اعلامی ${faDigits(w.quotedMinutes)} دقیقه</p><div class="wait-actions"><button data-status="seated">میز گرفت</button><button data-status="${w.status==='called'?'waiting':'called'}">${w.status==='called'?'بازگشت به انتظار':'اعلام به مشتری'}</button></div>`;item.querySelectorAll('button').forEach(btn=>btn.onclick=()=>updateWaitlist(w.id,btn.dataset.status));list.appendChild(item)})}
async function updateWaitlist(id,status){const response=await fetch(`${operationsUrl('/waitlist')}/${encodeURIComponent(id)}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({status})});if(response.ok)await fetchOperations()}
function fillOpsTables(selected=''){const select=document.querySelector('#opsTableSelect');select.innerHTML='<option value="">انتخاب میز</option>';(opsData?.tables||[]).filter(t=>t.reservable&&t.manualStatus!=='inactive').forEach(t=>{const option=document.createElement('option');option.value=t.id;option.textContent=`${t.name} · ${faDigits(t.capacity)} نفره${t.liveStatus==='available'?'':' · '+({occupied:'مشغول',upcoming:'رزرو آینده',awaiting:'منتظر ورود',dirty:'نظافت'})[t.liveStatus]}`;option.selected=t.id===selected;select.appendChild(option)})}
function openOpsReservation(reservation=null){document.querySelector('#opsReservationForm').reset();document.querySelector('#opsTrackingCode').value=reservation?.trackingCode||'';document.querySelector('#opsFormTitle').textContent=reservation?'ویرایش رزرو':'ثبت رزرو تلفنی یا حضوری';document.querySelector('#opsCustomerName').value=reservation?.customerName||'';document.querySelector('#opsCustomerMobile').value=reservation?.mobile||'';document.querySelector('#opsSource').value=reservation?.source==='walk_in'?'walk_in':'phone';document.querySelector('#opsSource').disabled=!!reservation;document.querySelector('#opsReservationStatus').value=reservation?.status||'confirmed';setJalaliInput(document.querySelector('#opsReservationDate'),reservation?.date||isoValue(document.querySelector('#opsDate'))||isoDate(new Date()));document.querySelector('#opsReservationTime').value=reservation?.time||new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());document.querySelector('#opsPartySize').value=reservation?.partySize||2;document.querySelector('#opsCustomerNote').value=reservation?.notes||'';document.querySelector('#opsInternalNote').value=reservation?.internalNotes||'';document.querySelector('#opsFormError').textContent='';fillOpsTables(reservation?.tableIds?.[0]||'');opsReservationDialog.showModal()}
document.querySelector('#opsReservationForm').onsubmit=async e=>{e.preventDefault();const code=document.querySelector('#opsTrackingCode').value,button=document.querySelector('#saveOperationalReservation'),error=document.querySelector('#opsFormError'),payload={customerName:document.querySelector('#opsCustomerName').value,mobile:latinDigits(document.querySelector('#opsCustomerMobile').value),source:document.querySelector('#opsSource').value,status:document.querySelector('#opsReservationStatus').value,date:isoValue(document.querySelector('#opsReservationDate')),time:document.querySelector('#opsReservationTime').value,partySize:Number(document.querySelector('#opsPartySize').value),tableIds:[document.querySelector('#opsTableSelect').value],notes:document.querySelector('#opsCustomerNote').value,internalNotes:document.querySelector('#opsInternalNote').value};button.disabled=true;error.textContent='';try{if(!payload.date)throw new Error('تاریخ رزرو را از تقویم شمسی انتخاب کنید.');const response=await fetch(code?`${operationsUrl('/reservations')}/${encodeURIComponent(code)}`:operationsUrl('/reservations'),{method:code?'PATCH':'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw new Error(data.message||'ذخیره رزرو انجام نشد');opsReservationDialog.close();await Promise.all([fetchOperations(),fetchAvailability()])}catch(err){error.textContent=err.message}finally{button.disabled=false}};
document.querySelector('#waitlistForm').onsubmit=async e=>{e.preventDefault();const error=document.querySelector('#waitFormError'),payload={customerName:document.querySelector('#waitCustomerName').value,mobile:latinDigits(document.querySelector('#waitCustomerMobile').value),partySize:Number(document.querySelector('#waitPartySize').value),quotedMinutes:Number(document.querySelector('#waitQuoted').value),notes:document.querySelector('#waitNotes').value};error.textContent='';try{const response=await fetch(operationsUrl('/waitlist'),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw new Error(data.message||'ثبت لیست انتظار انجام نشد');waitlistDialog.close();document.querySelector('#waitlistForm').reset();await fetchOperations()}catch(err){error.textContent=err.message}};
function tehranClientNow(){const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).filter(part=>part.type!=='literal').map(part=>[part.type,part.value]));return {date:`${parts.year}-${parts.month}-${parts.day}`,hour:Number(parts.hour),minute:Number(parts.minute)}}
function roundedFloorTime(){const now=tehranClientNow(),minutes=Math.floor(now.minute/30)*30;return `${String(now.hour).padStart(2,'0')}:${String(minutes).padStart(2,'0')}`}
async function openOperations(){adminDialog.close();applyManagerAccess();opsDialog.classList.toggle('table-only',!hasManagerPermission('reservations.read')&&!hasManagerPermission('waitlist.read'));setJalaliInput(document.querySelector('#opsDate'),tehranClientNow().date);document.querySelector('#opsFloorTime').value=roundedFloorTime();document.querySelector('#opsBranch').value=currentBranch;opsDialog.showModal();await fetchOperations();clearInterval(opsRefreshTimer);opsRefreshTimer=setInterval(()=>{if(opsDialog.open)fetchOperations()},45000)}
function exitOperations(){clearInterval(opsRefreshTimer);opsDialog.close();adminDialog.showModal()}
document.querySelector('#openOperations').onclick=openOperations;document.querySelector('#opsExit').onclick=exitOperations;document.querySelector('#opsMobileExit').onclick=exitOperations;document.querySelector('#opsRefresh').onclick=fetchOperations;document.querySelector('#opsDate').onchange=fetchOperations;document.querySelector('#opsFloorTime').onchange=fetchOperations;document.querySelector('#opsFloorNow').onclick=()=>{document.querySelector('#opsFloorTime').value=roundedFloorTime();fetchOperations()};document.querySelector('#opsBranch').onchange=e=>switchBranch(e.target.value,true);document.querySelector('#opsSearch').oninput=renderOperationalReservations;document.querySelector('#opsStatusFilter').onchange=renderOperationalReservations;document.querySelector('#addOperationalReservation').onclick=()=>openOpsReservation();document.querySelector('#opsAddQuick').onclick=()=>openOpsReservation();document.querySelector('#addWaitlist').onclick=()=>{document.querySelector('#waitFormError').textContent='';waitlistDialog.showModal()};

function fillPaymentSettings(){document.querySelector('#depositEnabled').checked=Boolean(cafeSettings.depositEnabled);document.querySelector('#depositMode').value=cafeSettings.depositMode||'fixed';document.querySelector('#depositAmount').value=Math.round(Number(cafeSettings.depositAmountRials||0)/10);document.querySelector('#depositPeakOnly').checked=Boolean(cafeSettings.depositPeakOnly);document.querySelector('#depositPeakStart').value=cafeSettings.depositPeakStart||'18:00';document.querySelector('#depositPeakEnd').value=cafeSettings.depositPeakEnd||'22:00';document.querySelector('#paymentDeadline').value=String(cafeSettings.paymentDeadlineMinutes||15);document.querySelector('#refundPolicy').value=cafeSettings.refundPolicy||''}
async function fetchPayments(){const error=document.querySelector('#paymentsError');error.textContent='';try{const branch=activeBranchProfile(),params=managerSession?.role==='owner'?`?branch=${encodeURIComponent(branch.id)}`:'',response=await fetch(`/api/payments${params}`),data=await response.json();if(!response.ok)throw new Error(data.message||'دریافت تراکنش‌ها انجام نشد.');document.querySelector('#paymentsPaid').textContent=money(data.summary.paid);document.querySelector('#paymentsPending').textContent=`${money(data.summary.pending)} · ${faDigits(data.summary.pendingCount)} رزرو`;document.querySelector('#paymentsRefunded').textContent=money(data.summary.refunded);const list=document.querySelector('#paymentsList');if(!data.transactions.length){list.innerHTML='<div class="insight-empty">هنوز تراکنشی برای این شعبه ثبت نشده است.</div>';return}list.innerHTML='';data.transactions.forEach(item=>{const row=document.createElement('article'),isRefund=item.type==='refund';row.innerHTML=`<span class="transaction-icon ${isRefund?'refund':'paid'}">${isRefund?'↩':'✓'}</span><div><b>${escapeHtml(item.customerName)}</b><small>${escapeHtml(item.trackingCode)} · ${escapeHtml(item.branchName)} · ${formatPersianDate(item.createdAt)}</small></div><strong>${isRefund?'−':'+'}${money(item.amountRials)}</strong>${!isRefund&&data.canWrite?'<button type="button">بازپرداخت</button>':''}`;row.querySelector('button')?.addEventListener('click',async()=>{if(!confirm('بیعانه بازپرداخت و رزرو لغو شود؟'))return;const refund=await fetch(`/api/payments/${encodeURIComponent(item.id)}/refund`,{method:'POST'}),result=await refund.json();if(!refund.ok){error.textContent=result.message||'بازپرداخت انجام نشد';return}await Promise.all([fetchPayments(),fetchAvailability()])});list.appendChild(row)})}catch(err){error.textContent=err.message}}
async function openPayments(){adminDialog.close();document.querySelector('#paymentsBranch').value=currentBranch;fillPaymentSettings();paymentsDialog.showModal();await fetchPayments()}
document.querySelector('#openPayments').onclick=openPayments;document.querySelector('#refreshPayments').onclick=fetchPayments;document.querySelector('#paymentsBranch').onchange=async event=>{await switchBranch(event.target.value);fillPaymentSettings();await fetchPayments()};
document.querySelector('#savePaymentSettings').onclick=async()=>{const button=document.querySelector('#savePaymentSettings'),error=document.querySelector('#paymentsError'),branch=activeBranchProfile(),payload={...cafeSettings,cafeName:cafeProfile.cafe.name,branchName:branch.name,city:branch.city,address:branch.address,depositEnabled:document.querySelector('#depositEnabled').checked,depositMode:document.querySelector('#depositMode').value,depositAmountRials:Number(document.querySelector('#depositAmount').value)*10,depositPeakOnly:document.querySelector('#depositPeakOnly').checked,depositPeakStart:document.querySelector('#depositPeakStart').value,paymentDeadlineMinutes:Number(document.querySelector('#paymentDeadline').value),depositPeakEnd:document.querySelector('#depositPeakEnd').value,refundPolicy:document.querySelector('#refundPolicy').value};button.disabled=true;error.textContent='';try{const response=await fetch(settingsUrl(),{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}),data=await response.json();if(!response.ok)throw new Error(data.message||'ذخیره تنظیمات انجام نشد.');cafeSettings=data;fillPaymentSettings();button.textContent='ذخیره شد ✓';setTimeout(()=>button.textContent='ذخیره قوانین بیعانه',1400)}catch(err){error.textContent=err.message}finally{button.disabled=false}};

document.querySelector('.dash-top span').textContent=`امروز، ${formatPersianDate(new Date())}`;
async function initializeApp(){const profile=await loadCafeProfile();if(profile.configured)applyCafeProfile(profile);renderCustomerMap();await Promise.all([fetchMap(),fetchSettings()]);await fetchAvailability()}
initializeApp();
